
/* ============================================================
   RIP & SHIP — the pack-cracking counter. Tear the foil with
   your thumb, flip the stack one card at a time, and make the
   call on every pull: SHIP it for fast coin, or KEEP it in the
   binder. The ledger line tells you if the pack paid.
   ============================================================ */
(function(){
if(typeof startReveal !== "function" || window.__rzWrap) return;
window.__rzWrap = true;

const RZ_PACK_IMG = "data:image/webp;base64,";
/* One tint per pack, spaced by the golden angle so no two land on a similar
   colour. The hash this replaced took (h%10)*36, which collided three ways on
   the real shelf - Legends & Myth, Cosmos & Terra and Mega Booster all came
   out 0deg, identical to each other AND to the untinted art. Spacing off the
   shelf index instead guarantees at least 20deg between any two, and leaves
   the starter pack on 0 so it wears the artwork's own green. A lot or a grant
   that is not on the shelf falls back to the hash, well clear of the shelf. */
function rzHue(key){
  let i = -1;
  try{ i = PACKS.findIndex(p => p.key === key); }catch(e){}
  if(i < 0){
    let h = 0;
    for(let j=0;j<(key||"").length;j++) h = (h*31 + key.charCodeAt(j)) >>> 0;
    i = 11 + (h % 23);
  }
  return Math.round(i * 137.508) % 360;
}
const RZ_SIGILS = {"blue": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"], "purple": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"], "red": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"], "gold": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]};
/* ---------- the fx layer: sparkles, poofs, confetti, sigil blooms ---------- */
let rzFxCv = null, rzFxG = null, rzFxP = [], rzFxRun = false;
function rzFxEnsure(){
  const ov = document.getElementById("rzOverlay");
  if(!ov) return null;
  if(!rzFxCv || rzFxCv.parentElement !== ov){
    rzFxCv = document.createElement("canvas");
    rzFxCv.id = "rzFx";
    ov.appendChild(rzFxCv);
    rzFxG = rzFxCv.getContext("2d");
  }
  rzFxCv.width = ov.clientWidth; rzFxCv.height = ov.clientHeight;
  return rzFxG;
}
function rzFxLoop(){
  if(!rzFxRun) return;
  requestAnimationFrame(rzFxLoop);
  const g = rzFxG; if(!g) return;
  g.clearRect(0,0,rzFxCv.width,rzFxCv.height);
  const grav = 340;
  for(let i=rzFxP.length-1;i>=0;i--){
    const p = rzFxP[i];
    p.life -= 1/60;
    if(p.life <= 0){ rzFxP.splice(i,1); continue; }
    p.x += p.vx/60; p.y += p.vy/60;
    if(p.kind !== "ring") p.vy += grav*p.g/60;
    const a = Math.min(1, p.life/(p.max*0.55));
    if(p.kind === "spark"){
      g.globalAlpha = a;
      g.fillStyle = p.col;
      g.save(); g.translate(p.x,p.y); g.rotate(p.rot += p.vr/60);
      g.fillRect(-p.s/2,-p.s/2,p.s,p.s*0.4);
      g.restore();
    } else if(p.kind === "star"){
      g.globalAlpha = a;
      g.fillStyle = p.col;
      g.font = `${p.s}px system-ui`; g.textAlign="center";
      g.fillText("✦", p.x, p.y);
    } else if(p.kind === "puff"){
      g.globalAlpha = a*0.5;
      g.fillStyle = p.col;
      g.beginPath(); g.arc(p.x, p.y, p.s*(1.6 - p.life/p.max), 0, 7); g.fill();
    } else if(p.kind === "ring"){
      g.globalAlpha = a;
      g.strokeStyle = p.col; g.lineWidth = 4*a+1;
      g.beginPath(); g.arc(p.x, p.y, p.s*(1 - p.life/p.max)*2.4 + 6, 0, 7); g.stroke();
    }
  }
  g.globalAlpha = 1;
  if(!rzFxP.length){ rzFxRun = false; g.clearRect(0,0,rzFxCv.width,rzFxCv.height); }
}
function rzFx(list){
  if(!rzFxEnsure()) return;
  rzFxP.push(...list);
  if(!rzFxRun){ rzFxRun = true; rzFxLoop(); }
}
function rzBurst(x, y, col, opts){
  const o = Object.assign({ n:26, sp:260, kind:"spark", s:7, g:1, life:0.9 }, opts||{});
  const out = [];
  for(let i=0;i<o.n;i++){
    const a = Math.random()*6.283, v = o.sp*(0.35+Math.random()*0.75);
    out.push({ kind:o.kind, x, y, vx:Math.cos(a)*v, vy:Math.sin(a)*v - o.sp*0.25,
      s:o.s*(0.6+Math.random()*0.9), col: Array.isArray(col)? col[i%col.length] : col,
      g:o.g, life:o.life*(0.6+Math.random()*0.6), max:o.life, rot:Math.random()*6, vr:(Math.random()-0.5)*14 });
  }
  rzFx(out);
}
function rzPoof(x, y, col){
  rzFx([{ kind:"ring", x, y, s:60, col, life:0.55, max:0.55, vx:0, vy:0, g:0 }]);
  rzBurst(x, y, ["#e8e2d6","#cfc6b4", col], { n:12, sp:120, kind:"puff", s:16, g:-0.12, life:0.85 });
}
function rzSigil(tier){
  const setKey = tier >= 15 ? "gold" : tier >= 12 ? "red" : tier >= 9 ? "purple" : "blue";
  const arr = RZ_SIGILS[setKey];
  return arr[Math.floor(Math.random()*arr.length)];
}
const RZ_CARDBACK = "data:image/webp;base64,";
/* ---------- earnable card backs ----------
   One back is worn at a time and the whole hand wears it. Conditions are
   checked at four moments: pack open (BEFORE this pack's pulls land, so a
   toast can never spoil a mythic sitting face-down in the hand), after a
   ship, on each flip, and at the summary. Owned/equipped live in
   state.ripship and ride the normal save. */
const RZ_BACKS = [
  { id:"cream",   name:"Wrapper Cream",  need:"yours from the start", img:RZ_CARDBACK,
    test:()=>true },
  { id:"ribbons", name:"The Ribbons",    need:"open 25 packs", img:"data:image/webp;base64,",
    test:()=>(state.packsOpened||0) >= 25 },
  { id:"gold",    name:"Gold Foil",      need:"ship 100 cards", img:"data:image/webp;base64,",
    test:()=>rzBk().shipN >= 100 },
  { id:"knot",    name:"The Golden Knot", need:"pull a Mythic", img:"data:image/webp;base64,",
    test:()=>{ try{
      for(const id in state.owned){ if(state.owned[id] > 0 && cards[+id] && cards[+id].rarity === 15) return true; }
    }catch(e){} return false; } },
  { id:"teal",    name:"The Night Star", need:"own every rarity, Junk to Mythic", img:"data:image/webp;base64,",
    test:()=>{ try{
      const got = new Array(16).fill(false);
      for(const id in state.owned){ if(state.owned[id] > 0 && cards[+id]) got[cards[+id].rarity] = true; }
      return got.every(Boolean);
    }catch(e){} return false; } },
  { id:"red",     name:"Crimson Press",  need:"rip 10 packs in one sitting", img:"data:image/webp;base64,",
    test:()=>rzStreak >= 10 },
];
function rzBk(){
  if(!state.ripship || typeof state.ripship !== "object") state.ripship = {};
  const r = state.ripship;
  if(!r.backs || typeof r.backs !== "object") r.backs = {};
  r.backs.cream = 1;
  if(typeof r.shipN !== "number" || !isFinite(r.shipN)) r.shipN = 0;
  if(!r.eq || !r.backs[r.eq]) r.eq = "cream";
  return r;
}
function rzBackImg(){
  const bk = rzBk();
  const d = RZ_BACKS.find(b=>b.id === bk.eq) || RZ_BACKS[0];
  return d.img;
}
function rzCheckBacks(){
  const bk = rzBk();
  let won = null;
  for(const b of RZ_BACKS){
    if(bk.backs[b.id]) continue;
    let hit = false; try{ hit = !!b.test(); }catch(e){}
    if(hit){ bk.backs[b.id] = 1; won = b; }
  }
  if(won){
    try{ saveState(); }catch(e){}
    try{ showToast(`🎴 New card back earned: ${won.name} — tap 🎴 backs in the hand to wear it`); }catch(e){}
  }
}
/* The hand: every undecided pull fanned face-down in an arc, the way a hand
   of cards is actually held. Slot spacing and rotation tighten as the hand
   grows, so a 30-card ten-pack still fits the box. The centre slot is the
   active card - lifted, glowing, and the one that takes the tap. */
function rzFanHtml(n, skipTop){
  if(n <= 0) return "";
  /* a ten-pack holds fifty pulls - fan only the nearest thirteen, the rest sit
     hidden behind them; the hint line carries the true count. Uncapped, the
     arc's lift term reached 200px+ and the hand swallowed the whole screen. */
  const shown = Math.min(n, 13);
  const step = Math.min(30, 290/shown), rot = Math.min(4.5, 46/shown), mid = (shown-1)/2;
  const jTop = Math.round(mid);
  let html = "";
  for(let j=0;j<shown;j++){
    const sl = j - mid;
    const top = !skipTop && j === jTop;
    const lift = top ? -14 : Math.min(22, Math.pow(Math.abs(sl), 1.25)*4);
    const z = top ? 22 : 20 - Math.ceil(Math.abs(sl));
    html += `<div class="rz-hcard${top?" top":""}"${top?` id="rzStack"`:""}
      style="transform:translateX(${(sl*step).toFixed(1)}px) translateY(${lift.toFixed(1)}px) rotate(${(sl*rot).toFixed(2)}deg); z-index:${Math.max(1,z)}">
      <div class="rz-hface" style="--d:${Math.abs(sl).toFixed(1)}"><img src="${rzBackImg()}" alt="" draggable="false"/></div>
    </div>`;
  }
  return html;
}
/* ---------- card art on the flip ----------
   Three layers, best available wins, emoji is the instant floor:
   1. PAINTED ART for Rare and up: art/<subject-slug>.webp, committed to the
      repo by the bench in waves (see docs/art-brief.md). Keyed by SUBJECT,
      not card id, so "Bald Eagle - Sketch Plate" wears the Bald Eagle. A
      miss costs one cheap 404 per subject per session, then falls through.
   2. WIKI PHOTO for everything else: the same ciLookup the card-info panel
      uses, so the two share one 90-day cache and one alias table.
   3. The emoji, which was already on screen before either fetch started. */
const RZ_ART_MIN = 9;                    /* Rare and up get painted art */
const rzArtMiss = {};                    /* subjects that 404'd this session */
function rzArtSlug(name){
  return name.split(" \u2014 ")[0].toLowerCase()
    .normalize("NFKD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}
function rzSetArt(c, src){
  const h = document.getElementById("rzArt");
  if(!h || !RZ || RZ.face !== c) return;   /* the hand moved on */
  const img = document.createElement("img");
  img.className = "rz-artimg"; img.alt = ""; img.draggable = false;
  img.src = src;
  h.innerHTML = ""; h.appendChild(img);
}
function rzLoadArt(c){
  const wiki = ()=>{ try{
    if(typeof ciLookup !== "function") return;
    ciLookup(c.name.split(" \u2014 ")[0])
      .then(e=>{ if(e && e.img) rzSetArt(c, e.img); }).catch(()=>{});
  }catch(e){} };
  if(c.rarity >= RZ_ART_MIN){
    const slug = rzArtSlug(c.name);
    if(rzArtMiss[slug]) return wiki();
    const probe = new Image();
    probe.onload  = ()=> rzSetArt(c, probe.src);
    probe.onerror = ()=>{ rzArtMiss[slug] = 1; wiki(); };
    probe.src = "art/" + slug + ".webp";
  } else wiki();
}
let RZ = null;                     /* live session */
let rzStreak = 0;                  /* packs ripped this sitting */

/* What a card is honestly WORTH: the price the collection screen pays for it,
   graded on the same curve the market uses. Not the market's BUY price - that
   is what a card costs you, roughly five times what anyone pays for it, and
   pricing a pull off it turns every pack into free money. */
function rzVal(card){
  try{
    let v = MARKET_SELL_PRICE_BY_TIER[card.rarity];
    const g = state.grading && state.grading.graded && state.grading.graded[card.id];
    if(g) v = Math.round(v * (0.5 + g*0.15));
    if(v > 0) return Math.max(2, Math.round(v));
  }catch(e){}
  return Math.max(2, Math.round(2 * Math.pow(2.05, card.rarity)));
}
/* SHIP is the impatient sale: the money lands now, and the 15% is what that
   convenience costs against carrying the card to the collection screen. */
function rzShipPay(card){ return Math.round(rzVal(card) * 0.85); }

const _origStartReveal = startReveal;
startReveal = function(pack, packsArr, spentCredits){
  try{
    rzCheckBacks();   /* retroactive only - this pack's pulls have not landed yet */
    const allPulls = packsArr.reduce((a,p)=>a.concat(p), []);
    const gains = applyPulls(allPulls);
    try{ saveState(); renderHeader(); renderPackShelf(); }catch(e){}
    RZ = { pack, pulls: allPulls, idx: 0, tear: 0, tearing:false,
           spent: spentCredits || 0, shipped: 0, keptVal: 0, stage: "rip",
           best: allPulls.reduce((a,c)=> (!a || c.rarity > a.rarity) ? c : a, null) };
    rzOpen();
  }catch(e){
    try{ _origStartReveal(pack, packsArr, spentCredits); }catch(e2){}
  }
};

function rzOpen(){
  let ov = document.getElementById("rzOverlay");
  if(!ov){
    ov = document.createElement("div");
    ov.id = "rzOverlay";
    document.body.appendChild(ov);
  }
  ov.style.display = "flex";
  rzRender();
}
function rzClose(){
  const ov = document.getElementById("rzOverlay");
  if(ov) ov.style.display = "none";
  RZ = null;
  try{ saveState(); renderHeader(); renderCollection && renderCollection(); }catch(e){}
}
function rzTally(){
  const net = RZ.shipped + RZ.keptVal - RZ.spent;
  return `<div class="rz-tally">
    <span>🎁 ${RZ.pack.icon||"🎴"} <b>${RZ.pack.name}</b>${RZ.spent?` · cost $${RZ.spent.toLocaleString()}`:""}</span>
    <span>📦 shipped <b>$${RZ.shipped.toLocaleString()}</b> · 🗃️ kept <b>$${RZ.keptVal.toLocaleString()}</b></span>
    <span class="${net>=0?"up":"down"}">${net>=0?"▲ up":"▼ down"} $${Math.abs(net).toLocaleString()}</span>
  </div>`;
}
function rzRender(){
  const ov = document.getElementById("rzOverlay");
  if(!ov || !RZ) return;
  if(RZ.stage === "rip"){
    const hue = rzHue(RZ.pack.key||"basic");
    ov.innerHTML = `<div class="rz-box">
      ${rzTally()}
      <div class="rz-pack" id="rzPack" style="--tear:${(RZ.tear*100).toFixed(1)}%; --hue:${hue}deg">
        <div class="rz-cap" style="background-image:url('${RZ_PACK_IMG}')"></div>
        <div class="rz-body" style="background-image:url('${RZ_PACK_IMG}')"></div>
        <div class="rz-tearline"></div>
        <div class="rz-packname">${RZ.pack.icon||"🎴"} ${RZ.pack.name} · ${RZ.pulls.length} cards</div>
      </div>
      <div class="rz-hint">👉 drag across the seam to SLICE the top off</div>
    </div>`;
    const pk = document.getElementById("rzPack");
    let lastX = null;
    const move = (x)=>{
      if(!RZ || RZ.stage !== "rip") return;   /* the drag can outlive the slice */
      if(lastX !== null){ RZ.tear = Math.min(1, RZ.tear + Math.abs(x-lastX)/220); }
      lastX = x;
      pk.style.setProperty("--tear", (RZ.tear*100).toFixed(1)+"%");
      if(RZ.tear >= 1) rzRipDone();
    };
    pk.onpointerdown = (e)=>{ RZ.tearing = true; lastX = e.clientX; pk.setPointerCapture(e.pointerId);
      RZ.tear = Math.min(1, RZ.tear + 0.2); move(e.clientX); };
    pk.onpointermove = (e)=>{ if(RZ && RZ.tearing) move(e.clientX); };
    pk.onpointerup = ()=>{ if(RZ) RZ.tearing = false; lastX = null; };
  }
  else if(RZ.stage === "cards"){
    const c = RZ.pulls[RZ.idx];
    const left = RZ.pulls.length - RZ.idx;
    const deal = !RZ.dealt; RZ.dealt = true;   /* the slide-out plays once, as the pack opens */
    ov.innerHTML = `<div class="rz-box">
      ${rzTally()}
      <div class="rz-hand${deal?" deal":""}">${rzFanHtml(left, false)}</div>
      <div class="rz-hint">${left} card${left===1?"":"s"} in hand · tap the front one to turn it</div>
      <div class="rz-row"><button class="rz-btn dim" id="rzBacksBtn">🎴 backs</button>
      <button class="rz-btn dim" id="rzKeepAll">🗃️ keep the rest</button></div>
    </div>`;
    document.getElementById("rzStack").onclick = ()=>{
      if(RZ.flipping) return;
      RZ.flipping = true;
      const f = document.querySelector("#rzStack .rz-hface");
      if(f) f.classList.add("rz-flipout");
      setTimeout(()=>{ if(RZ) rzFlip(c); }, 130);
    };
    document.getElementById("rzBacksBtn").onclick = ()=>{ RZ.stage = "backs"; rzRender(); };
    document.getElementById("rzKeepAll").onclick = ()=>{
      for(let i=RZ.idx; i<RZ.pulls.length; i++) RZ.keptVal += rzVal(RZ.pulls[i]);
      RZ.stage = "done"; rzRender();
    };
  }
  else if(RZ.stage === "backs"){
    const bk = rzBk();
    ov.innerHTML = `<div class="rz-box">
      <div class="rz-doneh">CARD BACKS</div>
      <div class="rz-hint">every pack you rip wears the one you choose</div>
      <div class="rz-bgrid">` + RZ_BACKS.map(b=>{
        const own = !!bk.backs[b.id], eq = bk.eq === b.id;
        return `<div class="rz-bcell${own?"":" locked"}${eq?" eq":""}" data-back="${b.id}">
          <img src="${b.img}" alt="" draggable="false"/>
          <div class="rz-bname">${b.name}</div>
          <div class="rz-bneed">${own ? (eq ? "wearing it" : "tap to wear") : "🔒 " + b.need}</div>
        </div>`;
      }).join("") + `</div>
      <div class="rz-row"><button class="rz-btn keep" id="rzBacksBack">back to the hand</button></div>
    </div>`;
    ov.querySelectorAll("[data-back]").forEach(el=>{
      el.onclick = ()=>{
        const bk2 = rzBk();
        if(!bk2.backs[el.dataset.back]) return;
        bk2.eq = el.dataset.back;
        try{ saveState(); }catch(e){}
        rzRender();
      };
    });
    document.getElementById("rzBacksBack").onclick = ()=>{ RZ.stage = "cards"; rzRender(); };
  }
  else if(RZ.stage === "face"){
    const c = RZ.face, r = RARITIES[c.rarity];
    const pay = rzShipPay(c);
    const sig = c.rarity >= 9 ? rzSigil(c.rarity) : null;
    const behind = RZ.pulls.length - RZ.idx - 1;   /* still face-down in the hand */
    ov.innerHTML = `<div class="rz-box">
      ${rzTally()}
      ${sig ? `<img class="rz-sigil ${c.rarity>=14?"big":""}" src="${sig}" alt=""/>` : ""}
      <div class="rz-hand faced">${rzFanHtml(behind, true)}
      <div class="rz-card ${c.rarity>=14?"burst":""}" style="--rc:${r.color}; border-color:${r.color}">
        <div class="rz-rname" style="color:${r.color}">${r.name}</div>
        <div class="rz-art" id="rzArt">${c.emoji}</div>
        <div class="rz-cname">${c.name}</div>
        <div class="rz-cat">${c.category}</div>
        <div class="rz-badges"><span class="rz-b ${c._wasNew?"new":"dupe"}">${c._wasNew?"NEW":"DUPLICATE"}</span>
        <span class="rz-val">worth $${rzVal(c).toLocaleString()}</span></div>
      </div>
      </div>
      <div class="rz-row">
        <button class="rz-btn ship" id="rzShip">📦 SHIP IT +$${pay.toLocaleString()}</button>
        <button class="rz-btn keep" id="rzKeep">🗃️ KEEP</button>
      </div>
    </div>`;
    rzLoadArt(c);
    document.getElementById("rzShip").onclick = ()=>{
      if(RZ.leaving) return;
      if(state.owned[c.id] > 0){
        state.owned[c.id] -= 1;
        if(!(state.owned[c.id] > 0)){
          try{ if(state.grading && state.grading.graded) delete state.grading.graded[c.id]; }catch(e){}
        }
        try{ state.miningBonus = computeMiningBonusFromOwned(state.owned); }catch(e){}
        state.dollars += pay;
        RZ.shipped += pay;
        rzBk().shipN += 1;
        rzCheckBacks();
        try{ fbSfxSafe && fbSfxSafe("reward_good", 0.35); }catch(e){}
      }
      rzAway();
    };
    document.getElementById("rzKeep").onclick = ()=>{
      if(RZ.leaving) return;
      RZ.keptVal += rzVal(c);
      try{ fbSfxSafe && fbSfxSafe("equip", 0.25); }catch(e){}
      rzAway();
    };
  }
  else if(RZ.stage === "done"){
    rzStreak += 1;
    rzCheckBacks();
    const net = RZ.shipped + RZ.keptVal - RZ.spent;
    const b = RZ.best, br = b ? RARITIES[b.rarity] : null;
    const canAgain = RZ.pack.price1 > 0 && state.dollars >= RZ.pack.price1 && typeof buyPacks === "function";
    ov.innerHTML = `<div class="rz-box">
      <div class="rz-doneh">${net >= 0 ? "📈 THE PACK PAID" : "📉 THE HOUSE WINS THIS ONE"}</div>
      <div class="rz-donenet ${net>=0?"up":"down"}">${net>=0?"+":"−"}$${Math.abs(net).toLocaleString()}</div>
      ${b ? `<div class="rz-bestline">best pull: <b style="color:${br.color}">${b.emoji} ${b.name}</b> (${br.name})</div>` : ""}
      <div class="rz-statline">📦 shipped $${RZ.shipped.toLocaleString()} · 🗃️ kept $${RZ.keptVal.toLocaleString()} · 🔥 streak ${rzStreak}</div>
      <div class="rz-row">
        ${canAgain ? `<button class="rz-btn ship" id="rzAgain">RIP ANOTHER — $${RZ.pack.price1.toLocaleString()}</button>` : ""}
        <button class="rz-btn keep" id="rzDone">back to the shelf</button>
      </div>
    </div>`;
    const ag = document.getElementById("rzAgain");
    if(ag) ag.onclick = ()=>{ const k = RZ.pack.key; rzClose(); try{ buyPacks(k, 1); }catch(e){} };
    document.getElementById("rzDone").onclick = rzClose;
    try{ saveState(); renderHeader(); }catch(e){}
  }
}
function rzRipDone(){
  if(RZ.ripping) return;
  RZ.ripping = true;
  const pk = document.getElementById("rzPack");
  if(pk){
    pk.classList.add("sliced");
    try{
      const r = pk.getBoundingClientRect(), ov = document.getElementById("rzOverlay").getBoundingClientRect();
      const cx = r.left - ov.left + r.width/2, cy = r.top - ov.top + 46;
      rzPoof(cx, cy, "#ffd35c");
      rzBurst(cx, cy, ["#ffd35c","#ff9a5c","#e8e2d6","#8fd0ff"], { n:34, sp:330, s:8, life:1.1 });
    }catch(e){}
    try{ fbSfxSafe && fbSfxSafe("treasure", 0.4); }catch(e){}
    setTimeout(()=>{ if(!RZ) return; RZ.ripping = false; RZ.stage = "cards"; rzRender(); }, 620);
  } else {
    RZ.ripping = false; RZ.stage = "cards"; rzRender();
  }
}
function rzFlip(c){
  RZ.flipping = false;
  RZ.face = c;
  RZ.stage = "face";
  rzCheckBacks();   /* the flipped card is revealed now, so a mythic may unlock the knot */
  setTimeout(()=>{
    try{
      const el = document.querySelector(".rz-card");
      if(!el) return;
      const r = el.getBoundingClientRect(), ov = document.getElementById("rzOverlay").getBoundingClientRect();
      const cx = r.left - ov.left + r.width/2, cy = r.top - ov.top + r.height/2;
      const col = RARITIES[c.rarity].color;
      if(c.rarity >= 15){
        rzPoof(cx, cy, col);
        rzBurst(cx, cy, [col,"#ffd35c","#ffffff"], { n:46, sp:420, kind:"star", s:22, g:0.35, life:1.5 });
        rzBurst(cx, cy, [col,"#ffd35c"], { n:30, sp:300, s:8, life:1.2 });
      } else if(c.rarity >= 12){
        rzPoof(cx, cy, col);
        rzBurst(cx, cy, [col,"#ffd35c"], { n:30, sp:320, kind:"star", s:17, g:0.5, life:1.1 });
      } else if(c.rarity >= 9){
        rzBurst(cx, cy, [col,"#e8e2d6"], { n:20, sp:240, s:7, life:0.9 });
      } else if(c.rarity >= 6){
        rzBurst(cx, cy, [col], { n:10, sp:170, s:5, life:0.7 });
      }
    }catch(e){}
  }, 60);
  if(c.rarity >= 15 && typeof triggerMythicFireworksEvent === "function"){
    try{ if(!state.settings || state.settings.flashingEnabled !== false) triggerMythicFireworksEvent(); }catch(e){}
  }
  rzRender();
}
/* the decided card leaves the hand before the fan closes ranks */
function rzAway(){
  if(RZ.leaving) return;
  RZ.leaving = true;
  const el = document.querySelector(".rz-card");
  if(el) el.classList.add("rz-away");
  setTimeout(()=>{ if(RZ) rzNext(); }, 230);
}
function rzNext(){
  RZ.leaving = false;
  RZ.idx += 1;
  RZ.stage = RZ.idx >= RZ.pulls.length ? "done" : "cards";
  try{ saveState(); renderHeader(); }catch(e){}
  rzRender();
}
})();


